class Solution:
    def isValidPalindrome(self, s, k):
        from functools import lru_cache
        @lru_cache(None)
        def dfs(l, r):
            if l >= r:
                return 0
            if s[l] == s[r]:
                return dfs(l + 1, r - 1)
            return 1 + min(dfs(l + 1, r), dfs(l, r - 1))
        return dfs(0, len(s) - 1) <= k

solutions.optimal:
class Solution:
    def isValidPalindrome(self, s, k):
        n = len(s)
        dp = [1] * n
        for l in range(n - 2, -1, -1):
            prev = 0
            for r in range(l + 1, n):
                old = dp[r]
                if s[l] == s[r]:
                    dp[r] = prev + 2
                else:
                    dp[r] = max(dp[r], dp[r - 1])
                prev = old
        return n - dp[-1] <= k

